(()=>{'use strict';const $=id=>document.getElementById(id),oldPreview=abrirModalVisualizarRdo;abrirModalVisualizarRdo=function(id){for(const a of document.querySelectorAll('.mpdf-download'))a.remove();oldPreview(id);const c=$('vrdo-conteudo-detalhado');if(c&&!c.querySelector('.mpdf-logo')){const img=document.createElement('img');img.className='mpdf-logo';img.src=MartinsLogoPdf;img.alt='Logo da Construtora Martins';c.prepend(img);}};
const oldHtml=window.gerarHtmlImpressaoUnicoRdo;if(typeof oldHtml==='function')window.gerarHtmlImpressaoUnicoRdo=function(...a){return '<img class="mpdf-logo" alt="Logo da Construtora Martins" src="'+MartinsLogoPdf+'">'+oldHtml.apply(this,a);};
const oldPrint=executarImpressaoOficial;executarImpressaoOficial=function(...a){const s=$('p-signatures-block');if(s)s.style.display=/PROPOSTA|ORÇAMENTO/i.test($('p-titulo-doc')?.textContent||'')?'none':'';return oldPrint.apply(this,a);};
let busy=false,url=null;async function photo(data){if(/^data:image\/(png|jpe?g);base64,/i.test(data))return data;if(!/^data:image\/webp;base64,/i.test(data))throw Error('Formato');const img=new Image();img.src=data;await img.decode();const canvas=document.createElement('canvas');canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;canvas.getContext('2d').drawImage(img,0,0);return canvas.toDataURL('image/jpeg',.9);}
async function download(docs,name){if(busy)return false;busy=true;try{showToast('Gerando arquivo PDF...');const r=await MartinsPdfRdo.generate(docs,{logo:MartinsLogoPdf,normalizePhoto:photo});if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(new Blob([r.bytes],{type:'application/pdf'}));for(const a of document.querySelectorAll('.mpdf-download'))a.remove();for(const id of ['modal-visualizar-rdo','modal-compartilhar','modal-compartilhar-rdo','modal-sucesso-orcamento']){const modal=$(id);if(!modal)continue;const a=document.createElement('a');a.className='mpdf-download';a.href=url;a.download=name;a.textContent='Baixar PDF gerado — '+name;const open=document.createElement('a');open.className='mpdf-download';open.href=url;open.target='_blank';open.rel='noopener';open.textContent='Abrir PDF';modal.firstElementChild?.append(a,open);}const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();showToast(r.warnings.length?'PDF gerado com observações: '+r.warnings.join(' '):'PDF pronto com o logo. Se o download não iniciar, use Baixar PDF gerado ou Abrir PDF.');return r;}catch(e){showToast('PDF não gerado: '+e.message,'warning');return false;}finally{busy=false;}}
imprimirRdo=function(id){const r=getDb().find(x=>x.id===id);if(!r){showToast('RDO não encontrado.','warning');return false;}return download([r],MartinsPdfRdo.filename(r));};window.imprimirLoteRdosPorLista=rows=>download([...(rows||[])].sort((a,b)=>String(a.data).localeCompare(String(b.data))),'RDOs_Martins.pdf');window.imprimirOrcamentoVendaPdf=id=>{const q=window.getOrcamentosVendasDb().find(x=>x.id===id);if(!q){showToast('Orçamento não encontrado.','warning');return false;}return download([MartinsPdfRdo.proposal(q)],'Orcamento_'+String(q.num||q.id).replace(/[^\w-]/g,'_')+'.pdf');};
function labels(){if($('btn-print-from-view-rdo'))$('btn-print-from-view-rdo').textContent='Baixar PDF';if($('btn-imprimir-pdf-share'))$('btn-imprimir-pdf-share').textContent='1. Baixar PDF';}document.addEventListener('DOMContentLoaded',labels);labels();})();
